/**
 * Candidates with ids generated by code, and the validation of the model's answer against them (T7.2, ASK-4).
 *
 * The model is the one that decides buy, sell or hold; the code never turns a zone's side into an order. What the code
 * guarantees is the boundary: the model chooses among ids that the code produced from real data (zones, on-chain tokens,
 * spot and perpetual instruments, or the option to keep), and anything outside that set is discarded. A free sentence, an
 * invented id, an invented action, a price or a size from the model never travels on as an instruction or a number.
 *
 * Pure: no clock, no network, no disk.
 */
import type { BriefCandidate } from "./brief";
import type { Zone } from "./zones";

export const HOLD_CANDIDATE: BriefCandidate = { id: "manter", tipo: "manter" };

const bps = (level: number, price: number): number => Math.round(((level - price) / price) * 10_000) + 0;

/** The zones worth showing the model: active or tested only, with distances in basis points of the current price. */
export function zoneCandidates(zones: readonly Zone[], price: number): BriefCandidate[] {
  if (!Number.isFinite(price) || price <= 0) return [];
  return zones
    .filter((zone) => zone.estado === "ativa" || zone.estado === "testada")
    .map((zone) => ({
      id: `zona:${zone.id}`,
      tipo: "zona" as const,
      limitesBps: [bps(zone.baixo, price), bps(zone.alto, price)] as const,
      nota: Math.round(zone.nota * 100) / 100,
      fatores: [...zone.fatores],
      idadeBarras: zone.idadeBarras,
      estado: zone.estado,
      invalidacaoBps: zone.invalidacao === null ? null : bps(zone.invalidacao, price),
    }));
}

export const spotCandidate = (instId: string): BriefCandidate => ({ id: `spot:${instId}`, tipo: "spot" });
export const perpCandidate = (instId: string): BriefCandidate => ({ id: `perp:${instId}`, tipo: "perp" });

/** An EVM address is case-insensitive and is lowercased; other chains (Solana) are case-sensitive and kept as they are. */
export function tokenCandidate(token: { readonly chainIndex: string; readonly address: string; readonly nota?: number }): BriefCandidate {
  const address = /^0x[0-9a-fA-F]+$/.test(token.address) ? token.address.toLowerCase() : token.address;
  return { id: `token:${token.chainIndex}:${address}`, tipo: "token", ...(token.nota === undefined ? {} : { nota: Math.round(token.nota * 100) / 100 }) };
}

export function candidateIds(candidates: readonly BriefCandidate[]): ReadonlySet<string> {
  const ids = new Set<string>();
  for (const candidate of candidates) {
    if (ids.has(candidate.id)) throw new Error(`duplicate candidate id ${candidate.id}`);
    ids.add(candidate.id);
  }
  return ids;
}

export type Action = "buy" | "sell" | "hold";

export interface Decision {
  readonly action: Action;
  /** One of the ids the code produced; null on hold. */
  readonly candidateId: string | null;
  /** The weights the model says it gave to each kind of evidence, or null when absent or malformed. */
  readonly pesos: Readonly<Record<string, number>> | null;
}

export type DecisionResult =
  | { readonly ok: true; readonly decision: Decision }
  | { readonly ok: false; readonly reason: "not_an_object" | "action_invalid" | "candidate_invalid" | "candidate_required" | "candidate_unknown" | "candidate_not_allowed_on_hold" };

const ACTIONS: readonly string[] = ["buy", "sell", "hold"];
const MAX_WEIGHTS = 8;
const WEIGHT_NAME = /^[A-Za-z][A-Za-z0-9_]{0,23}$/;

function cleanWeights(raw: unknown): Record<string, number> | null {
  if (raw === null || typeof raw !== "object" || Array.isArray(raw)) return null;
  const entries = Object.entries(raw as Record<string, unknown>);
  if (entries.length === 0 || entries.length > MAX_WEIGHTS) return null;
  const out: Record<string, number> = {};
  for (const [name, value] of entries) {
    if (!WEIGHT_NAME.test(name) || typeof value !== "number" || !Number.isFinite(value) || value < 0 || value > 1) return null;
    out[name] = value;
  }
  return out;
}

/**
 * Accepts the model's parsed answer only if it is `{ action, candidateId, pesos? }` with a known action and an id from
 * `ids`. Every other field is ignored and never copied, so nothing the model invents can travel on.
 */
export function validateDecision(raw: unknown, ids: ReadonlySet<string>): DecisionResult {
  if (raw === null || typeof raw !== "object" || Array.isArray(raw)) return { ok: false, reason: "not_an_object" };
  const answer = raw as Record<string, unknown>;
  const action = answer.action;
  if (typeof action !== "string" || !ACTIONS.includes(action)) return { ok: false, reason: "action_invalid" };
  const id = answer.candidateId;
  if (id !== undefined && id !== null && typeof id !== "string") return { ok: false, reason: "candidate_invalid" };
  const pesos = cleanWeights(answer.pesos);

  if (action === "hold") {
    if (id === undefined || id === null || id === HOLD_CANDIDATE.id) return { ok: true, decision: { action: "hold", candidateId: null, pesos } };
    return { ok: false, reason: "candidate_not_allowed_on_hold" };
  }
  if (id === undefined || id === null || id === HOLD_CANDIDATE.id) return { ok: false, reason: "candidate_required" };
  if (!ids.has(id)) return { ok: false, reason: "candidate_unknown" };
  return { ok: true, decision: { action: action as Action, candidateId: id, pesos } };
}
